            put(facts, 'reason_', [event, disability_ids[disability_local_id]])
        if type(record.get('termination_date')) is str:
            put(facts, 'start_', [event, record.get('termination_date')])
    retirement_keys = set()
    for index, record in enumerate(retirements):
        if not support(witnesses, record, public, True):
            complete = False
            continue
        local_id = record.get('local_id')
        person = record.get('person')
        disability_local_id = record.get('disability_local_id')
        if record.get('source_basis') != 'explicit_retirement' or type(local_id) is not str or local_id in retirement_keys or type(person) is not str or (disability_local_id is not None and disability_local_id not in disability_ids):
            complete = False
            continue
        retirement_keys.add(local_id)
        event = 'retirement_' + str(index)
        put(facts, 'retirement_', [event])
        put(facts, 'agent_', [event, person])
        if type(disability_local_id) is str:
            put(facts, 'reason_', [event, disability_ids[disability_local_id]])
        if type(record.get('retirement_date')) is str:
            put(facts, 'start_', [event, record.get('retirement_date')])
    if type(service_target) is str and len(services) > 0 and service_matches != 1:
        complete = False
        add(reasons, 'queried_service_role_not_uniquely_aligned')
    if type(payment_target) is str and len(payments) > 0 and payment_matches != 1:
        complete = False
        add(reasons, 'queried_payment_role_not_uniquely_aligned')
    if not complete:
        add(reasons, component + '_one_or_more_records_unread_or_invalid')
    return part(facts, negatives, witnesses, complete, reasons)

def apply(inputs, premises):
    component = inputs['component_id']
    view = inputs['view']
    public = inputs['public_case']
    facts = []
    negatives = []
    witnesses = []
    reasons = []
    complete = True
    if type(view) is not dict or view.get('extraction_status') != 'complete':
        return part([], [], [], False, [component + '_unread_or_ambiguous'])
    if not support(witnesses, view, public, True):
        complete = False
        add(reasons, component + '_complete_view_requires_current_facts_witness')
    records = view.get('returns')
    if type(records) is not list:
        return part(facts, negatives, witnesses, False, reasons + ['return_channel_unread'])
    for index, record in enumerate(records):
        if not support(witnesses, record, public, True):
            complete = False
            continue
        persons = record.get('persons')
        year = record.get('year')
        kind = record.get('return_type')
        expected = 'explicit_joint_return' if kind == 'joint' else 'explicit_separate_return'
        if kind not in ('joint', 'separate') or record.get('source_basis') != expected or type(persons) is not list or len(persons) == 0 or not all(type(person) is str for person in persons) or type(year) is not int:
            complete = False
            continue
        if kind == 'joint':
            event = 'joint_return_' + str(index)
            put(facts, 'joint_return_', [event])
            for person in persons:
                put(facts, 'agent_', [event, person])
            put(facts, 'start_', [event, str(year) + '-01-01'])
            put(facts, 'end_', [event, str(year) + '-12-31'])
    if not complete:
        add(reasons, component + '_one_or_more_records_unread_or_invalid')
    return part(facts, negatives, witnesses, complete, reasons)
